using Aspire.Hosting.Testing;

namespace MyApp.Evaluation;

public sealed class AppHostFixture : IAsyncLifetime
{
    public DistributedApplication App { get; private set; } = null!;

    public async ValueTask InitializeAsync()
    {
        var builder = await DistributedApplicationTestingBuilder
            .CreateAsync<Projects.MyApp_AppHost>();

        App = await builder.BuildAsync();
        await App.StartAsync();
    }

    public async ValueTask DisposeAsync()
    {
        await App.DisposeAsync();
    }
}

using Aspire.Hosting.Testing;

namespace MyApp.Evaluation;

public sealed class EvaluationTests : IClassFixture<AppHostFixture>
{
    private readonly AppHostFixture _fixture;

    public EvaluationTests(AppHostFixture fixture)
    {
        _fixture = fixture;
    }

    [Fact]
    public async Task AppHost_StartsSuccessfully()
    {
        // Verify the distributed application started without errors
        Assert.NotNull(_fixture.App);
    }

    [Fact]
    public async Task AppHost_AllResourcesRunning()
    {
        // Verify all declared resources reach a running state
        await _fixture.App.WaitForResources().WaitAsync(TimeSpan.FromSeconds(60));
    }
}

